t = int(input())
for _ in range(t):
    a = list(map(int, input().split()))
    hople = []
    for x in a:
            hople.append(x)
    if len(hople) < 3:
        print("-1")
    else:
        hople.sort()
        tong = hople[0] + hople[1] + hople[2]
        print(tong)

file2.full_code:
so = int(input())
for i in range(so):
    n = list(map(int, input().split()))
    chuoi = []
    for i in range(len(n)-2):
        if abs(n[i] - n[i+1]) == abs(n[i+1] - n[i+2]):
            chuoi.append(n[i])
            chuoi.append(n[i+1])
            chuoi.append(n[i+2])
    ds = []
    for i in chuoi:
        if i not in ds:
            ds.append(i)
    ds.sort()
    tong = ds[0] + ds[1] + ds[2]
    print(tong)

